NS_IMETHODIMP
nsImapMailFolder::SetupMsgWriteStream(nsIFile* aFile) {
  nsresult rv;
  aFile->Remove(false);
  m_tempMessageStreamBytesWritten = 0;
  rv = MsgNewBufferedFileOutputStream(
      getter_AddRefs(m_tempMessageStream), aFile,
      PR_WRONLY | PR_CREATE_FILE | PR_TRUNCATE, 00700);
  return rv;
}
